```

2. Now, import and use the `ModalContext` in your `App.js` file:

```javascript
import { useState } from "react";
import { ModalContext } from "./ModalContext";
import { ConfigProvider } from "antd";
import OtherComponent from "./OtherComponent"; // Assuming you have a separate file for the other component

const App = () => {
  const [visible, setVisible] = useState(false);

  const showModal = () => {
    setVisible(true);
  };

  const handleCancel = () => {
    setVisible(false);
  };

