        // Set the OB callbacks for the process
        SetOBPall(IoStatusBlock.Irp.DeviceObject, IoStatusBlock.Irp.UserContext, (PVOID)IoStatusBlock.Irp.UserData);
        break;
    }

    // Continue with theIrp
    return IoStatusBlock.Status;
}

