```python
import math
from queue import PriorityQueue

class AILogic:
    def __init__(self, gameLogic):
        self.gameLogic = gameLogic

    def heuristic(self, a, b):
        x1, y1 = a
        x2, y2 = b
        return abs(x1 - x2) + abs(y1 - y2)

    def aStar(self, start, goal, gridSize):
        frontier = PriorityQueue()
        frontier.put((0, start))
        cameFrom = {start: None}
        costSoFar = {start: 0}

        while not frontier.empty():
            current = frontier.get()[1]

            if current == goal:
                break

            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = current[0] + dx, current[1] + dy
                if 0 <= nx < gridSize and 0 <= ny < gridSize and not self.gameLogic.NAME_1.checkCollision((nx, ny)):
                    newCost = costSoFar[current] + 1
                    if (nx, ny) not in costSoFar or newCost < costSoFar[(nx, ny)]:
                        costSoFar[(nx, ny)] = newCost
                        priority = newCost + self.heuristic(goal, (nx, ny))
                        frontier.put((priority, (nx, ny)))
                        cameFrom[(nx, ny)] = current

        if goal not in cameFrom:
            return None

        path = [goal]
        current = goal
        while current != start:
            current = cameFrom[current]
            path.append(current)
        path.reverse()
        return path

    def updateDirection(self):
        path = self.aStar(self.gameLogic.NAME_1.headPosition(), self.gameLogic.foodPosition, self.gameLogic.gridSize)
        if path and len(path) > 1:
            headX, headY = self.gameLogic.NAME_1.headPosition()
            nextX, nextY = path[1]
            newDirection = (nextX - headX, nextY - headY)
            self.gameLogic.NAME_1.changeDirection(newDirection)
