class Board:
    def __init__(self):
        self.board_state = np.zeros((3, 3, 3), dtype=int)

    def update_board(self, move, NAME_1_id):
        row, col, depth = move
        self.board_state[row, col, depth] = NAME_1_id

    def validate_move(self, move):
        row, col, depth = move
        if 0 <= row < 3 and 0 <= col < 3 and 0 <= depth < 3:
            return self.board_state[row, col, depth] == 0
        else:
            return False

    def display_board(self):
        vis = o3d.visualization.Visualizer()
        vis.create_window()

        for row in range(3):
            for col in range(3):
                for depth in range(3):
                    cell_value = self.board_state[row, col, depth]
                    if cell_value != 0:
                        shape = o3d.geometry.Text3D(f"{cell_value}", size=10, pos=[row * 20, col * 20, depth * 20])
                        vis.add_geometry(shape)
        vis.run()
        vis.destroy_window()

